bool GetDef(int index, const CThingObjectDef** out)
{
    if (index < 0 || index >= NDEFS || !g_exists[index]) return false;
    *out = &g_things[index];
    return true;
}
bool GetSubDef(const CThingObjectDef* def, const CAppearanceModifierDef** out)
{
    if (!def->Modifier) return false;
    *out = def->Modifier;
    return true;
}

